public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int cardC = sc.nextInt();
    int b = sc.nextInt();
    int state = Math.max(cardC, b);
    int y = Math.min(cardC, b);
    boolean equal = true;
    if(state == y) {
      System.out.println(state);
      equal = false;
    }
    state %= y;
    int max = 0;
    for(int i = Math.min(state, y); i > 0; i--) {
      if(state % i == 0 && y % i == 0) {
        max = i;
        break;
      }
    }
    if(equal) {
      System.out.println(max);
    }
  }
}

