import java.util.Scanner;

public class Main {

	public static void main(String[] atgs) {
		Scanner sc = new Scanner(System.in);
		int yesCount = sc.nextInt();
		int y = sc.nextInt();
		int gcd = 0;
		if (yesCount == y) {
			gcd = yesCount;
		} else {
			gcd = calculation(yesCount, y, gcd);
		}
		System.out.println(gcd);
		sc.close();
	}

	public static int calculation(int yesCount, int y, int gcd) {
		if (yesCount < y) {
			int tmp = yesCount;
			yesCount = y;
			y = tmp;
		}
		yesCount %= y;
		for (int i = yesCount; true; i--) {
			if (yesCount % i == 0 && y % i == 0) {
				gcd = i;
				break;
			}
		}
		return gcd;
	}
}

