public class Main {
	public static void main (String [] args) {
		Scanner scan = new Scanner (System.in);

		//２つの自然数入力
		int strLst = scan.nextInt();
		int y = scan.nextInt();
		scan.close();

		int gcd;


		if ( strLst == y) {
			gcd = strLst;
		} else {
			if (strLst > y) {
				int n = strLst % y;
				gcd = Gcd(y,n);
			}else {
				int n = y % strLst;
				 gcd = Gcd(strLst,n);
			}
		}

		System.out.println(gcd);

	}

	//最大公約数を求める
	public static int Gcd(int strLst, int y) {

		int n = Math.min(strLst, y);

		for (int i = n; i >= 1; i--) {
			if (strLst % i == 0 && y % i == 0) {
				return i;
			}
		}

		return 1;
	}
}

