import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) {
		try {
			final BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
			final String[] line = in.readLine().split(" ");
			in.close();

			final int in_T = Integer.parseInt(line[0]);
			final int y = Integer.parseInt(line[1]);

			System.out.println(String.valueOf(euclidean(in_T, y)));
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	public static int euclidean(final int in_T, final int y) {
		int cnt_hei = in_T<y ? y : in_T;
		int D_T_S = in_T<y ? in_T : y;
		int r = cnt_hei % D_T_S;

		while (r != 0) {
			cnt_hei = D_T_S;
			D_T_S = r;
			r = cnt_hei % D_T_S;
		}

		return D_T_S;
	}
}

