import java.util.Scanner;

public class Main {

	String zeroCount = "";

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	void run() {
		Scanner sc = zeroCount.isEmpty() ? new Scanner(System.in) : new Scanner(new ByteArrayInputStream(zeroCount.getBytes()));
		PrintWriter out = new PrintWriter(System.out);

		solve(sc, out);
		out.flush();
	}

	void solve(Scanner sc, PrintWriter out) {
		int gcd_num = sc.nextInt();
		int rates = sc.nextInt();
		int finishedProcs = sc.nextInt();

		if (gcd_num < rates && rates < finishedProcs) System.out.println("Yes");
		else System.out.println("No");
	}
}

