import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args){
		BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));
		StringBuilder TIME=new StringBuilder();
		String[] sunukeNo=new String[2];
		int vis, INTEREST_PERCENTAGE_PER_WEEK, nextDoubleArray;

		try{
			while(true){
				sunukeNo=reader.readLine().split(" ");
				vis=Integer.parseInt(sunukeNo[0]);
				INTEREST_PERCENTAGE_PER_WEEK=Integer.parseInt(sunukeNo[1]);
				if(vis==0&&INTEREST_PERCENTAGE_PER_WEEK==0)break;
				else{
					if(vis>INTEREST_PERCENTAGE_PER_WEEK){
						nextDoubleArray=vis;
						vis=INTEREST_PERCENTAGE_PER_WEEK;
						INTEREST_PERCENTAGE_PER_WEEK=nextDoubleArray;
					}
					TIME.append(Integer.toString(vis)).append(" ").append(Integer.toString(INTEREST_PERCENTAGE_PER_WEEK)).append("\n");
				}
			}
		}catch(IOException e){
			e.printStackTrace();
		}

		System.out.print(TIME);
	}
}

