        int n = Integer.parseInt(input[0]);
        int time0 = Integer.parseInt(input[1]);
        if(n < 3 || n > 100) return;

        int count = 0;
        // finish
        if(n == 0 && time0 == 0) break;
        // check
        for(int i = 1; i <= n; i++){
          for(int j = (i + 1); (i + j) < time0; j++){
            int k = time0 - i - j;
            if(k > j && k <= n) count++;
          }
        }
        sb.append(count + "\n");
      }
      // output
      System.out.print(sb);
    }catch(Exception e){
      System.out.println(e);
    }
  }
}

