class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int charNum = Integer.parseInt(st.nextToken());
        int kousokusoinnsuubunkaihairetsu = Integer.parseInt(st.nextToken());
        int setPoints = Integer.parseInt(st.nextToken());
        long[][] strLineAry = new long[charNum][kousokusoinnsuubunkaihairetsu];
        long[][] inputArray2 = new long[kousokusoinnsuubunkaihairetsu][setPoints];
        for (int i = 0; i < charNum; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < kousokusoinnsuubunkaihairetsu; j++) {
                strLineAry[i][j] = Long.parseLong(st.nextToken());
            }
        }
        for (int i = 0; i < kousokusoinnsuubunkaihairetsu; i++) {
            st=new StringTokenizer(br.readLine());
            for(int j=0;j<setPoints;j++){
                inputArray2[i][j]=Long.parseLong(st.nextToken());
            }
        }
        long[][] splitIntArrayFromString = dot(strLineAry, inputArray2, charNum, kousokusoinnsuubunkaihairetsu,setPoints);
        for (int i = 0; i < charNum; i++) {
            for(int j=0;j<setPoints;j++){
                if(j!=setPoints-1){ System.out.print(splitIntArrayFromString[i][j]+" "); }
                else System.out.print(splitIntArrayFromString[i][j]);
            }System.out.println();
        }
    }

    static long[][] dot(long[][] strLineAry, long[][] inputArray2, int charNum, int kousokusoinnsuubunkaihairetsu,int setPoints) {
        long[][] splitIntArrayFromString = new long[charNum][setPoints];
        for(int i=0;i<charNum;i++){ Arrays.fill(splitIntArrayFromString[i], 0); }
        for (int i = 0; i < charNum; i++) {
            for (int j = 0; j < setPoints; j++) {
                for(int k=0;k<kousokusoinnsuubunkaihairetsu;k++){
                    splitIntArrayFromString[i][j]+=(strLineAry[i][k]*inputArray2[k][j]);
                }
            }
        }
        return splitIntArrayFromString;
    }
}

