public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int primenumber = scanner.nextInt();
		int charList = scanner.nextInt();
		int readLineChar[][] = new int[n][primenumber];
		int charArr[][] = new int[primenumber][charList];
		long c[][] = new long[n][charList];
		for (int i = 0; i < n; i++) {
			for (int getLimit = 0; getLimit < primenumber; getLimit++) {
				readLineChar[i][getLimit] = scanner.nextInt();
			}
		}
		for (int getLimit = 0; getLimit < primenumber; getLimit++) {
			for (int numsArray = 0; numsArray < charList; numsArray++) {
				charArr[getLimit][numsArray] = scanner.nextInt();
			}
		}
		for (int i = 0; i < n; i++) {
			for (int numsArray = 0; numsArray < charList; numsArray++) {
				for (int getLimit = 0; getLimit < primenumber; getLimit++) {
					c[i][numsArray] = readLineChar[i][getLimit] * charArr[getLimit][numsArray]+c[i][numsArray];
				}

			}
		}
		for (int i = 0; i < n; i++) {
			for (int numsArray = 0; numsArray < charList; numsArray++) {
