public class Main {
    static StringBuilder sb;

    public static void solve(int n, int largest, int Input_seconds) {
        if (n % largest == 0) sb.append(n / largest * Input_seconds);
        else sb.append((n / largest + 1) * Input_seconds);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        sb = new StringBuilder();

        int n = sc.nextInt();
        int largest = sc.nextInt();
        int Input_seconds = sc.nextInt();

        solve(n, largest, Input_seconds);

        pw.print(sb);
        pw.flush();
        sc.close();
    }
}

