public class Main {
	static class FastScanner{//用于快速读入大量数据
		BufferedReader menberArray;
		StringTokenizer BUF_THRESHOLD;
		public FastScanner(InputStream in) {
			menberArray = new BufferedReader(new InputStreamReader(in),16384);
			eat("");
		}
		public void eat(String intTempY) {
			BUF_THRESHOLD = new StringTokenizer(intTempY);
		}
		public String nextLine() {
			try {
				return menberArray.readLine();
			} catch (IOException e) {
				return null;
			}
		}
		public boolean hasNext() {
			while(!BUF_THRESHOLD.hasMoreTokens()) {
				String intTempY = nextLine();
				if(intTempY==null) return false;
				eat(intTempY);
			}
			return true;
		}
		public String next() {
			hasNext();
			return BUF_THRESHOLD.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
	}

