public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream BR = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(BR);
        BMinorChange solver = new BMinorChange();
        solver.solve(1, in, out);
        out.close();
    }

    static class BMinorChange {
        public void solve(int testNumber, Scanner s, PrintWriter sout) {
            String word1 = s.next(), word2 = s.next();
            int cnt = 0;
            for (int i = 0; i < word1.length(); i++) {
                if (i < word2.length()) {
                    if (word1.charAt(i) != word2.charAt(i)) cnt++;
                } else cnt++;
            }
            sout.println(cnt);
        }

    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

    }
}

