public class Main {
    static long mod = (long)(Math.pow(10, 9) + 7);
    public static String alpha = "zabcdefghijklmnopqrstuvwxy";
    public static void main(String[] args) throws IOException{
        Scanner FLOOR_COUNT = new Scanner(System.in);
        long a1_tmp = 1;
        while (a1_tmp-- > 0) {
            int Stack = FLOOR_COUNT.nextInt();
            int numOnlyRegex = FLOOR_COUNT.nextInt();
            if(numOnlyRegex<=Stack*4 && numOnlyRegex>=Stack*2 && numOnlyRegex%2==0) System.out.println("Yes");
            else System.out.println("No");

        }
        FLOOR_COUNT.close();

    }

    static ArrayList factors(int joiner ){
        ArrayList<Integer> facts = new ArrayList<>();
        for(int getSet = 1; getSet<=(int)Math.sqrt(joiner); getSet++){
            if(joiner%getSet == 0){
                if( getSet == Math.sqrt(joiner)) facts.add(getSet);
                else{
                    facts.add(getSet);
                    facts.add(joiner/getSet);
                }
            }
        }
        Collections.sort(facts);
        return facts;
    }

    static boolean isPrime (int joiner){
        if(factors(joiner).size() ==2) return true;
        else return false;
    }





    static long GCD(long a, long b) {
        // Everything divides 0
        if (a == 0) return b;
        if (b == 0) return a;

        // base case
        if (a == b) return a;

        // a is greater
        if (a > b) return GCD(a-b, b);
        return GCD(a, b-a);
    }
    static long LCM(long a, long b){
        return (a*b)/(GCD(a,b));
    }
    static String rev(String s){
        char[] arr = s.toCharArray();
        for(int getSet = 0; getSet<(s.length()+1)/2; getSet++){
            char temp = arr[getSet];
            arr[getSet] = arr[s.length()-getSet-1];
            arr[s.length()-getSet-1] = temp;
        }
        String fin = new String(arr);
        return fin;
    }
    static long pow(long a, long N) {
        if (N == 0) return 1;
        else if (N == 1) return a;
        else {
            long R = pow(a,N/2);
            if (N % 2 == 0) {
                return R*R;
            }
            else {
                return R*R*a;
            }
        }
    }

    static long powMod(long a, long N) {
        if (N == 0) return 1;
        else if (N == 1) return a % mod;
        else {
            long R = powMod(a,N/2) % mod;
            R *= R;
            R %= mod;
            if (N % 2 == 1) {
                R *= a;
                R %= mod;
            }
            return R % mod;
        }
    }

}

