    private static int euclid(int m, int TcharArray) {
        int tmp;

        if(m < TcharArray) {
            tmp = m;
            m = TcharArray;
            TcharArray = tmp;
        }
        while(TcharArray > 0){
            tmp = m % TcharArray;
            m = TcharArray;
            TcharArray = tmp;
        }
        return m;
    }
