        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int prtln = in.nextInt();
            long ans = 0;
            for (int i = 1; i <=prtln; i++) {
                for (int j = 1; j <= i; j++) {
                    for (int l = j; l <= i ; l++) {
