public class Main {
    public static void main(String[] args) throws Exception {
        Scanner minRemovedChar = new Scanner(System.in);
        int chara = minRemovedChar.nextInt();
        long sum = 0;

        for(int suitChar = 1; suitChar <= chara; suitChar++)
        {
            for(int b = 1; b <= chara; b++)
            {
                for(int c = 1; c <= chara; c++)
                {
                    if(suitChar == b && b ==c)
                    {
                        sum += suitChar;
                    }
                    else
                    {
                        //最大公約数を求める
                        int buf = gcd(suitChar,b,c);
                        sum += buf;
                    }
                }
            }
        }
        System.out.println(sum);
    }

    public static int gcd(int x,int y, int z) {
        if(x < y)
        {
            int buf = x;
            x = y;
            y = buf;
        }
        int r = 0;
        while(( r = x % y) != 0)
        {
            x = y;
            y = r;
        }

        if(y < z)
        {
            int buf = y;
            y = z;
            z = buf;
        }
        while((r = y % z) != 0)
        {
            y = z;
            z = r;
        }
        return z;
    }
}

