		int aString = 0;

		for(int syurui = 1; syurui <= intTempX; syurui++) {
			for(int x_3 = 1; x_3 <= intTempX; x_3++) {
				for (int TAROcard = 1; TAROcard <= intTempX; TAROcard++) {
