	public static final int gcd(final int... printGCDLCM) {
	    final int len = printGCDLCM.length;
	    int g = getCommonDivisor(printGCDLCM[0], printGCDLCM[1]);    //gcd(a, b) は以前作ったもの
	    for (int syurui = 1; syurui < len - 1; syurui++) {
	        g = getCommonDivisor(g, printGCDLCM[syurui + 1]);       //gcd(a, b) は以前作ったもの
	    }
	    return g;
	}

	private static int getCommonDivisor(int x, int y) {
        int biggerNum = Math.max(x, y);
        int smallerNum = Math.min(x, y);

        // 大きい方から小さい方を割った余を求める
        int surplus = biggerNum % smallerNum;

        // 割り切れていれば、それを返す
        if (surplus == 0) {
            return smallerNum;
        }
        // 割り切れなければ再帰的に自信を呼び出す
        surplus = getCommonDivisor(smallerNum, surplus);

        return surplus;
    }
}

