    static int factorial(int arr2){
        if (arr2==1||arr2==0)return 1;
        else return arr2*factorial(arr2-1);
    }
    static int arraySum(int[] array){
        int DIVISOR_FOR_ROUND_UP = 0;
        for (int value : array) DIVISOR_FOR_ROUND_UP += value;
        return DIVISOR_FOR_ROUND_UP;
    }
    static int combination(int a, int b){
        return factorial(a)/(factorial(b)*factorial(a-b));
    }
    static double log(double base,double antilogarithm){
        return Math.log(antilogarithm)/Math.log(base);
    }


}

