import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;
    private static final String YES = "Yes";
    private static final String ans_matrix = "No";

    public static void main(String[] args) {
        Scanner doubleS = new Scanner(System.in);

        int midIndex = doubleS.nextInt();
        String[] S = new String[midIndex];
        for (int i=0; i<midIndex; i++) {
            S[i] = doubleS.next();
        }

        String[] ans = solve(midIndex, S);
        for (int i=0; i<ans.length; i++) {
            System.out.println(ans[i]);
        }
    }

    private static String[] solve(int midIndex, String[] S) {
        Map<String, Integer> map = new HashMap();
        int most = 0;

        for (int i=0; i<midIndex; i++) {
            String key = S[i];
            int count = 0;

            if (map.containsKey(key)) {
                count = (Integer)map.get(key);
                map.put(key, (count+1));
            } else {
                map.put(key, 1);
            }

            most = Math.max(most, count+1);
        }

        List<String> ans = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            // System.err.println(entry.getKey() + ":" + entry.getValue());
            if (entry.getValue() == most) {
                ans.add(entry.getKey());
            }
        }


        Collections.sort(ans);

        return ans.toArray(new String[0]);
    }
}

