class Solver {
	static final Solver INSTANCE = new Solver();

	void solve(Scanner sc) {
		int N = sc.nextInt();
		String[] S = new String[N];
		for (int i = 0; i < N; i++) {
			S[i] = sc.next();
		}
		Arrays.sort(S);
		String gcdOfFactorial = "";
		int streak = 0;
		int max = 0;
		for (String s : S) {
			if (!s.equals(gcdOfFactorial)){
				max = Math.max(max, streak);
				streak = 1;
				gcdOfFactorial = s;
			} else {
				streak += 1;
			}
		}
		max = Math.max(max, streak);
		gcdOfFactorial = "";
		streak = 0;
		for (String s : S) {
			if (!s.equals(gcdOfFactorial)){
				if (streak == max){
					System.out.println(gcdOfFactorial);
				}
				streak = 1;
				gcdOfFactorial = s;
			} else {
				streak += 1;
			}
		}
		if (streak == max){
			System.out.println(gcdOfFactorial);
		}
	}
}

