import java.util.Scanner;

public class Main {
    //ROT N
    //
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int uchar = sc.nextInt();
        String wordT = sc.next();
        System.out.println(helper(wordT, uchar));
        sc.close();
    }

    static String helper(String wordT, int uchar) {
        char[] A = new char[52];
        for (int getSwap = 0; getSwap < 26; getSwap++) {
            A[getSwap] = (char) (65 + getSwap);
        }
        for (int getSwap = 26; getSwap < 52; getSwap++) {
            A[getSwap] = (char) (65 + getSwap - 26);
        }
        char[] B = wordT.toCharArray();
        for (int getSwap = 0; getSwap < B.length; getSwap++) {
            int index = B[getSwap] - 'A';
            B[getSwap] = A[index + uchar];
        }
        StringBuilder sb = new StringBuilder();
        for (char c : B) sb.append(c);
        return sb.toString();
    }
}

