public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h_cnt = Integer.parseInt(sc.next());
        long tsum = Long.parseLong(sc.next());
        int House = Integer.parseInt(sc.next());

        int[] A = new int[House];
        for (int i = 0; i < House; i++) {
            A[i] = Integer.parseInt(sc.next());
        }

        solve(h_cnt, House, tsum, A);
    }

    public static void solve(int n, int surface, long k, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < surface; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (surface - k >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

