		int q1_3 = sc.nextInt();
		int[] gcd_ans = new int[q1_3];
		int[] b = new int[q1_3];
		int[] c = new int[q1_3-1];

		for (int i = 0; i < q1_3; i++) {
			gcd_ans[i] = sc.nextInt();
		}

		for (int i = 0; i < q1_3; i++) {
			b[i] = sc.nextInt();
		}

		for (int i = 0; i < q1_3 - 1; i++) {
			c[i] = sc.nextInt();
		}

		// System.out.println(Arrays.toString(c));

		int res = 0;
		int prev = -1;
		for (int i = 0; i < q1_3; i++) {
			int k = prev + 1;
			if (prev != -1 && prev + 1 == gcd_ans[i]) {
				res += c[prev - 1]; 
			}
			res += b[gcd_ans[i] - 1];
			prev = gcd_ans[i];
		}

		System.out.println(res);
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
	            str = br.readLine();
	        } catch (IOException e) {
	            e.printStackTrace();
	        }
	        return str;
	      }
	  }
}

