        InputStream s_char = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(s_char);
        PrintWriter cards3 = new PrintWriter(outputStream);
        BBuffet solver = new BBuffet();
        solver.solve(1, in, cards3);
        cards3.close();
    }

    static class BBuffet {
        public void solve(int testNumber, Scanner in, PrintWriter cards3) {
            int n = in.nextInt();
            int a[] = ReadInput.readIntArray(n, in);
            int rChar[] = ReadInput.readIntArray(n, in);
            int c[] = ReadInput.readIntArray(n - 1, in);
            int prev = -1;
            long total = 0;
            for (int i = 0; i < n; i++) {
                int cur = a[i];
