                if (cur - prev == 1) {
                    total += c[prev - 1];
                }
                prev = cur;
            }
            cards3.println(total);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int a[] = new int[size];
            for (int i = 0; i < size; i++) {
                a[i] = in.nextInt();
            }
            return a;
        }

    }
