		int[] gcdLCM = new int[nlm];
		int[] bList = new int[nlm];
		int[] cList = new int[nlm - 1];
		for (int i = 0; i < nlm; i++) {
			gcdLCM[i] = Integer.parseInt(sc.next());
		}
		for (int i = 0; i < nlm; i++) {
