    Scanner sc = new Scanner(System.in);
    int numM, wd_t, timeStart = 0, nextLongMap = -1;
    numM = Integer.parseInt(sc.next());
    int[] order = new int[numM];
    int[] score = new int[numM];
    int[] additional = new int[numM-1];
    for(wd_t = 0; wd_t < numM; wd_t++) {
      order[wd_t] = Integer.parseInt(sc.next());
    }
    for(wd_t = 0; wd_t < numM; wd_t++) {
      score[wd_t] = Integer.parseInt(sc.next());
    }
    for(wd_t = 0; wd_t < numM-1; wd_t++) {
      additional[wd_t] = Integer.parseInt(sc.next());
    }
    for(wd_t = 0; wd_t < numM; wd_t++) {
      timeStart += score[order[wd_t] - 1];
