   */
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int modId = Integer.parseInt(sc.next());

    int[] checkPrimeNum = new int[modId];
    for (int i = 0; i < modId; i++) {
      checkPrimeNum[i] = Integer.parseInt(sc.next());
    }

    int[] b = new int[modId];
    for (int i = 0; i < modId; i++) {
      b[i] = Integer.parseInt(sc.next());
    }

    int[] c = new int[modId - 1];
    for (int i = 0; i < modId - 1; i++) {
      c[i] = Integer.parseInt(sc.next());
    }

    int longgcd = 0;
    for (int i = 0; i < modId; i++) {
      longgcd += b[checkPrimeNum[i] - 1];
      if(i > 0) {
        if (checkPrimeNum[i] - checkPrimeNum[i - 1] == 1) {
          longgcd += c[checkPrimeNum[i - 1] - 1];
        }
      }
    }

    System.out.println(longgcd);
  }

}

