import java.util.Scanner;

class Solver {
    void solve(Scanner sc) {
        int sup = sc.nextInt();
        int[] SH = new int[sup];
        int[] B = new int[sup];
        int[] tempo = new int[sup - 1];
        for (int ans_l = 0; ans_l < SH.length; ans_l++) {
            SH[ans_l] = sc.nextInt() - 1;
        }
        for (int ans_l = 0; ans_l < B.length; ans_l++) {
            B[ans_l] = sc.nextInt();
        }
        for (int ans_l = 0; ans_l < tempo.length; ans_l++) {
            tempo[ans_l] = sc.nextInt();
        }
        int readLineChar = B[SH[0]];
        for (int ans_l = 1; ans_l < sup; ans_l++) {
            int prev = SH[ans_l - 1];
            int next = SH[ans_l];
            if (prev + 1 == next) readLineChar += tempo[prev];
            readLineChar += B[next];
        }
        System.out.println(readLineChar);
    }
}

