class readS implements Closeable {
	private final InputStream in = System.in;
	private final byte[] readS = new byte[1024];
	private int Hayami = 0;
	private int charList = 0;
	private boolean HayamiSaori() {
		if (Hayami < charList) {
			return true;
		}else{
			Hayami = 0;
			try {
				charList = in.read(readS);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (charList <= 0) {
				return false;
			}
		}
		return true;
	}
	private int SaoriHayami() { 
		if (HayamiSaori()) {
            return readS[Hayami++];
         }else{
             return -1;
         }
	}
	private static boolean hayami_saori(int readS) { 
		return 33 <= readS && readS <= 126;
	}
	public boolean hayamisaori() { 
		while(HayamiSaori() && !hayami_saori(readS[Hayami])) Hayami++; return HayamiSaori();
	}
	public String nextHayami() {
		if (!hayamisaori()) throw new NoSuchElementException();
		StringBuilder hayamin = new StringBuilder();
		int charList = SaoriHayami();
		while(hayami_saori(charList)) {
			hayamin.appendCodePoint(charList);
			charList = SaoriHayami();
		}
		return hayamin.toString();
	}
	public long saorihayami() {//nextLong
		if (!hayamisaori()) throw new NoSuchElementException();
		long readS = 0;
		boolean misao = false;
		int charList = SaoriHayami();
		if (charList == '-') {
			misao = true;
			charList = SaoriHayami();
		}
		if (charList < '0' || '9' < charList) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= charList && charList <= '9') {
				readS *= 10;
				readS += charList - '0';
			}else if(charList == -1 || !hayami_saori(charList)){
				return misao ? -readS : readS;
			}else{
				throw new NumberFormatException();
			}
			charList = SaoriHayami();
		}
	}
	public int saori_hayami() {//nextInt
		long readS = saorihayami();
		if (readS < Integer.MIN_VALUE || readS > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) readS;
	}
	public double Hayamin() { //nextDouble
		return Double.parseDouble(nextHayami());
	}
	public void close() {
		try {
			in.close();
		} catch (IOException e) {
		}
    }

}

