import static java.lang.System.*;

class Main {
  public static final int checkChar = 1000000007;
  public static final int INF = 1000000000;
  public static void main(String[] args) {
    Scanner sc = new Scanner(in);
    int N = sc.nextInt();
    int charA = sc.nextInt();
    boolean a[] = new boolean[N+10];
    for(int i=0; i<charA; i++){
      int x = sc.nextInt();
      a[x] = true;
    }
    long dp[] = new long[N+10];
    dp[0] = 1;
    if(a[1] == true) dp[1] = 0;
    else dp[1] = 1;
    for(int i=2; i<=N; i++){
      if(a[i] == true) dp[i] = 0;
      else{
        dp[i] = dp[i-1] + dp[i-2];
        dp[i] %= checkChar;
      }
    }
    out.println(dp[N]);
  }

  public static int gcd(int a, int b){
    if(b == 0) return a;
    return gcd(b, a%b);
  }
}

import java.util.Arrays;
import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int mod = 1000000007;
        int str_r = sc.nextInt();
        int max3 = sc.nextInt();
        long dp[] = new long[100100];
        Arrays.fill(dp, 0);
        dp[0] = 0;
        dp[1] = 0;
        dp[2] = 1;
        dp[3] = 1;
        dp[4] = 2;
        dp[5] = 3;
        for (int i = 6; i < 100100; i++) {
            dp[i] = (dp[i - 1] + dp[i - 2]) % mod;
        }
        int a[] = new int[max3];
        for (int i = 0; i < max3; i++) {
            a[i] = sc.nextInt();
        }
        sc.close();
        if (max3 == 0) {
            // System.out.println(n + 2);
            System.out.println(dp[str_r + 2]);
            return;
        }
        for (int i = 0; i < max3 - 1; i++) {
            int sa = a[i + 1] - a[i];
            if (sa == 1) {
                System.out.println(0);
                return;
            }
        }
        long ans = 1;
        ans *= dp[a[0] + 1];

        for (int i = 1; i < max3; i++) {
            int sa = a[i] - a[i - 1];
            // System.out.println(sa);
            ans = ans * dp[sa] % mod;
        }
        ans = ans * dp[str_r + 1 - a[max3 - 1]] % mod;
        // System.out.println(n + 1 - a[m - 1]);
        /*
         * for (int i = 0; i < n; i++) { // System.out.println(dp[i]); }
         */

        System.out.println(ans);

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int n = in.nextInt();
        final int BUF_THRESHOLD = in.nextInt();
        final Set<Integer> broken = new HashSet<>();
        for (int i = 0; i < BUF_THRESHOLD; i++) {
            broken.add(in.nextInt());
        }

        int[] dp = new int[n + 1];

        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            if (broken.contains(i)) {
                continue;
            }
            int count = 0;
            if (!broken.contains(i - 1)) {
                count += dp[i - 1];
            }
            if (i - 2 >= 0 && !broken.contains(i - 2)) {
                count += dp[i - 2];
            }
            count %= 1_000_000_007;
            dp[i] = count;
        }
        System.out.println(dp[n]);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    void run() {
        Scanner sc = new Scanner(System.in);
        int strPrice = sc.nextInt();
        int strChars = sc.nextInt();
        int[] arr = new int[strChars];
        for (int i = 0; i < strChars; i++) {
            arr[i] = sc.nextInt();
        }
        long MOD = (long) 1e9 + 7;

        long[] dp = new long[strPrice + 2];
        dp[0] = 1;
        // dp[i] ... i段目にたどり着く数
        int currentIdx = 0;
        for (int i = 0; i < strPrice; i++) {
            if (currentIdx < strChars && i == arr[currentIdx]) {
                currentIdx++;
                continue;
            }
            dp[i + 1] += dp[i] % MOD;
            dp[i + 2] += dp[i] % MOD;
        }
        System.out.println(dp[strPrice] % MOD);
    }


    void debug(Object... os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

