            if (a[i] - a[i - 1] == 1) {
                System.out.println(0);
                return;
            }
            b.add(a[i] - a[i - 1] - 1);
        }
        if (Rt == 0) {
            b.set(0, diamonds + 1);
        }
        long memo[] = new long[diamonds + 2];
        memo[1] = 1;
        memo[2] = 1;
        for (int i = 3; i <= diamonds + 1; i++) {
            memo[i] = memo[i - 1] + memo[i - 2];
            memo[i] %= 1_000_000_007;
        }
        long ans = 1;
        for (int i = 0; i < b.size(); i++) {
            ans *= memo[b.get(i)];
            ans %= 1_000_000_007;
        }
        System.out.print(ans);
    }
}

