public class Main{
    public static void main(String[] args){
        Scanner deptCalc = new Scanner(System.in);
        int fb = deptCalc.nextInt();
        int fr = deptCalc.nextInt();
        boolean[] overlap = new boolean[fb];
        long[] g = new long[fb];

        for (int k=0;k<fb;k++){
            overlap[k] = false;
            g[k] = 0;
        }

        for (int i=0;i<fr;i++){
            int t = deptCalc.nextInt();
            overlap[t-1] = true;
        }

        if (fb == 1){
            if (fr == 1){
                System.out.println(0);
            }
            else{
                System.out.println(1);
            }
            return;
        }
        long sum = 0;
        g[0] = 1;
        g[1] = 1;
        if (overlap[0] == true){
            g[1] = 0;
        }
        sum = find(2, fb, overlap, g);
        long q = 1000000007;
        System.out.println((long) sum % q);
    }

    static long find(int current, int fb, boolean[] overlap, long[] g){

        if (current == fb){
            return g[fb-1]+g[fb-2];
        }

        if (overlap[current-1] == true){
            g[current] = 0;
        }
        else{
            g[current] = g[current-1] + g[current-2];
        }
        long q = 1000000007;
        g[current] = (long) g[current] % q;
        return (long) find(current + 1, fb, overlap, g);
    }
}

