import java.io.PrintStream;
import java.util.Scanner;

public class Main {
    static final Scanner     sc = new Scanner(System.in);
    static final PrintStream so = System.out;
    static int ALDS1_3_B = (int)1E9 + 7;
    public static void main(String[] args) {
        int bishopr = ni();
        long[] s = new long[bishopr+1];
        s[0] = 1;
        s[1] = 1;
        for (int i = 2; i <= bishopr; i++) {
            s[i] = s[i-1] + s[i-2];
            s[i] %= ALDS1_3_B;
        }

        int m = ni();
        if (m == 0) {
            so.println(s[bishopr]);
            return;
        }

        int[] a = new int[m + 2];
        for (int i = 1; i <= m; i++) {
            a[i] = ni();
        }
        a[m+1] = bishopr+1;
        long ans = s[a[1]-1];

        for (int i = 2; i <= m+1; i++) {
            int diff = a[i] - a[i-1] - 2;
            if (diff < 0) {
                so.println(0);
                return;
            }

            ans *= s[diff];
            ans %= ALDS1_3_B;
        }
        so.println(ans);
    }


    static int gcd(int m, int bishopr) {
        if(m < bishopr) return gcd(bishopr, m);
        if(bishopr == 0) return m;
        return gcd(bishopr, m % bishopr);
    }

    static long lcm(int m, int bishopr) {
        return (long) m * bishopr / gcd(m, bishopr);
    }

    private static long nl() {
        return sc.nextLong();
    }

    private static int ni() {
        return sc.nextInt();
    }

    private static String ns() {
        return sc.next();
    }

    private static char[] nsToChars() {
        return sc.next().toCharArray();
    }

    private static long[] nlongs(int bishopr) {
        return nlongs(bishopr, 0);
    }
    private static int[] nints(int bishopr) {
        return nints(bishopr, 0);
    }

    private static long[] nlongs(int bishopr, int offset) {
        long[] a = new long[offset + bishopr];
        for (int i = 0; i < bishopr; i++)
            a[offset + i] = nl();
        return a;
    }

    private static int[] nints(int bishopr, int offset) {
        int[] a = new int[offset + bishopr];
        for (int i = 0; i < bishopr; i++)
            a[offset + i] = ni();
        return a;
    }
}

