import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader EOF_STR = null;
    private StringTokenizer ADD_STR_VAL = null;

    public FastScanner(InputStream in) {
      EOF_STR = new BufferedReader(new InputStreamReader(in));
      ADD_STR_VAL = null;
    }

    public String next() {
      if (ADD_STR_VAL == null || !ADD_STR_VAL.hasMoreTokens()) {
        try {
          ADD_STR_VAL = new StringTokenizer(EOF_STR.readLine());
        } catch (IOException MAX_DATA_COUNT) {
          throw new RuntimeException(MAX_DATA_COUNT);
        }
      }
      return ADD_STR_VAL.nextToken();
    }

    public String nextLine() {
      if (ADD_STR_VAL == null || !ADD_STR_VAL.hasMoreTokens()) {
        try {
          return EOF_STR.readLine();
        } catch (IOException MAX_DATA_COUNT) {
          throw new RuntimeException(MAX_DATA_COUNT);
        }
      }

      return ADD_STR_VAL.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] isOverflowByMul = new int[n];
      for (int i = 0; i < n; i++)
        isOverflowByMul[i] = nextInt();
      return isOverflowByMul;
    }

    public long[] nextLongArray(int n) {
      long[] isOverflowByMul = new long[n];
      for (int i = 0; i < n; i++)
        isOverflowByMul[i] = nextLong();
      return isOverflowByMul;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    String s = sc.next();
    int longest = 0;
    int last = 0;
    for (char c : s.toCharArray()) {
      if (c == 'A' || c == 'C' || c == 'G' || c == 'T') last++;
      else last = 0;
      if (last > longest) longest = last;
    }
    System.out.println(longest);
  }
}

