import java.util.Scanner;

public class Main {


	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int inNumArrays = scan.nextInt();
		int max_r = scan.nextInt();
		int sub[] = new int[inNumArrays+1];
		for(int i=1;i<=inNumArrays;i++) {
			sub[i] = scan.nextInt();
		}

		int cost[] = new int[inNumArrays+1];
		cost[1] = 0;

		for(int i=2;i<=inNumArrays;i++) {
			int min = Integer.MAX_VALUE;
			for(int j=1;j<=max_r;j++) {
				if(i - j <=0) {
					break;
				}

				min = Math.min(min, Math.abs(sub[i]-sub[i-j]) + cost[i-j]);

			}

			cost[i] = min;

		}

		System.out.println(cost[inNumArrays]);
	}
}

