public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CLinovaAndKingdom solver = new CLinovaAndKingdom();
        solver.solve(1, in, out);
        out.close();
    }

    static class CLinovaAndKingdom {


        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), matchChar = in.nextInt();
            int a[] = new int[n];
            int dp[] = new int[n];
            for (int i = 0; i < n; i++) a[i] = in.nextInt();
            Arrays.fill(dp, (int) 1e9);
            dp[0] = 0;
            for (int i = 1; i < n; i++) {
                for (int j = 1; j <= matchChar; j++) {
                    if (i >= j) {
                        dp[i] = min(dp[i], dp[i - j] + Math.abs(a[i] - a[i - j]));
                    }
                }
            }
            out.println(dp[n - 1]);

        }

        public int max(int ...a) {
            int max = Integer.MIN_VALUE;
            for (int i : a) max = Math.max(max, i);
            return max;
        }

        public int min(int ...a) {
            int min = Integer.MAX_VALUE;
            for (int i : a) min = Math.min(min, i);
            return min;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

