		System.out.println(minCostJump(N, reg, H));
	}

	public static int minCostJump(int N, int reg, int[] H) {
		int[] cache = new int[N+1];

		for(int i = 2; i <= N; i++) {
			cache[i] = cache[i-1] + Math.abs(H[i-1] - H[i]);
			for(int j = i-2; j >= i-reg && j > 0; j--) {
				cache[i] = Math.min(cache[i], cache[j] + Math.abs(H[j]-H[i]));
			}
		}

		return cache[N];
	}
}

