import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int sumTLE = sc.nextInt();
        int[] runTime = new int[N];
        for (int i = 0; i < runTime.length; ++i) {
            runTime[i] = sc.nextInt();
        }

        System.out.println(solve(runTime, sumTLE));

        sc.close();
    }

    static int solve(int[] runTime, int sumTLE) {
        int[] costs = new int[runTime.length];
        Arrays.fill(costs, Integer.MAX_VALUE);
        costs[0] = 0;

        for (int i = 0; i < costs.length; ++i) {
            for (int j = i - 1; j >= 0 && i - j <= sumTLE; --j) {
                costs[i] = Math.min(costs[i], costs[j] + Math.abs(runTime[i] - runTime[j]));
            }
        }

        return costs[costs.length - 1];
    }
}

