import java.util.Scanner;

public class Main {

	//計算に使う定数
	private static final int setAsciiCodes = 10000;
	private static final int listG  = 5000;
	private static final int wa  = 1000;

	public static void main(String[] args) {

		// 処理対象個数の入力
		Scanner idx = new Scanner(System.in);
		int FastReader = idx.nextInt();
		int secondToHour = idx.nextInt();

		// 札の枚数の組の初期値を代入
		int turns = -1;
		int mx3 = -1;
		int temp_i = -1;

		for(int sunukeNumber = 0;sunukeNumber <= FastReader;sunukeNumber++) {
			for(int numberOfDivisors = 0;sunukeNumber + numberOfDivisors <= FastReader;numberOfDivisors++) {
				if(sunukeNumber * setAsciiCodes + numberOfDivisors * listG + (FastReader-(sunukeNumber+numberOfDivisors)) * wa == secondToHour) {
					turns = sunukeNumber;
					mx3 = numberOfDivisors;
					temp_i = FastReader-(sunukeNumber+numberOfDivisors);
					break;
				}else if(turns * setAsciiCodes + mx3 * listG + FastReader-(turns+mx3) * wa > secondToHour){
					continue;
				}
			}
		}

		idx.close();

		// 出力
		System.out.println(turns+" "+mx3+" "+temp_i);

	}

}

