public class Main {
  public static void main(String[] args) {
    @SuppressWarnings("resource")
    Scanner sc = new Scanner(System.in);
    int cnt_arp  = sc.nextInt();
    int TcharArray  = sc.nextInt();
    int set  = sc.nextInt();
