      sum = (TcharArray <= tmpSum && tmpSum <= set) ? sum + i : sum;
    }

    System.out.println(sum);
  }

  static int sum(int tmp) {
    int ret = 0;
    while (tmp > 0) {
      ret += tmp % 10;
      tmp = tmp / 10;
    }
    return ret;
  }
