import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        BTwoSwitches solver = new BTwoSwitches();
        solver.solve(1, in, out);
        out.close();
    }

    static class BTwoSwitches {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int a = in.nextInt();
            int sBeforeLength = in.nextInt();
            int max_num = in.nextInt();
            int nLongA = in.nextInt();
            int maxStart = Math.max(a, max_num);
            int minEnd = Math.min(sBeforeLength, nLongA);
            if (sBeforeLength <= max_num || nLongA <= a) {
                out.println(0);
            } else out.println(minEnd - maxStart);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int max_num = read();
            while (isSpaceChar(max_num)) {
                max_num = read();
            }
            int sgn = 1;
            if (max_num == '-') {
                sgn = -1;
                max_num = read();
            }
            int res = 0;
            do {
                if (max_num < '0' || max_num > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += max_num - '0';
                max_num = read();
            } while (!isSpaceChar(max_num));
            return res * sgn;
        }

        public boolean isSpaceChar(int max_num) {
            if (filter != null) {
                return filter.isSpaceChar(max_num);
            }
            return isWhitespace(max_num);
        }

        public static boolean isWhitespace(int max_num) {
            return max_num == ' ' || max_num == '\n' || max_num == '\r' || max_num == '\t' || max_num == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }
}

