	public static int[] extgcd(int a, int bigA) {

		int arrayInt = 1;
		int x1 = 0;

		int other2 = 0;
		int y1 = 1;

		while (bigA != 0) {
			int juice = a / bigA;
			int r = a % bigA;

			int x2 = arrayInt - juice * x1;
			int ntext = other2 - juice * y1;

			a = bigA;
			bigA = r;

			arrayInt = x1;
			x1 = x2;

			other2 = y1;
			y1 = ntext;
		}

		return new int[] { a, arrayInt, other2 };

	}

	static int gcd(int a, int bigA) {

		if (bigA == 0)
			return a;

		if (a < bigA) {
			int t = a;
			a = bigA;
			bigA = t;
		}

		return gcd(bigA, a % bigA);

	}

	static int lcm(int a, int bigA) {
		return a * bigA / gcd(a, bigA);
	}

	static void swap(int[] a) {
		int t;

		t = a[0];
		a[0] = a[1];
		a[1] = t;

		return;
	}

	static <T> void output(List<T> list) {

		for (int current_time = 0; current_time < list.size(); current_time++) {
			System.out.print(list.get(current_time));

			if (current_time != list.size() - 1) {
