public class Main {
    public static void main(String[] args) {
        Scanner moto = new Scanner(System.in);
        String MODE_DEBUG = moto.next();
        int[] parse = new int[26];
        int n = MODE_DEBUG.length();
        for (int first = 0; first < n; first++) {
            parse[(int) (MODE_DEBUG.charAt(first) - 'a')]++;
        }
        for (int first : parse) {
            if (first % 2 != 0) {
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");
    }
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner hasSweetsSunuke = new Scanner(System.in);
		String denominator = hasSweetsSunuke.next();
		String readBigDecimal = "";
		String cnt_len = "";
		for (int i = 0; i < denominator.length(); i++) {
			readBigDecimal = denominator.substring(i, i + 1);
			if (readBigDecimal.equals("0") | readBigDecimal.equals("1")) {
				cnt_len += readBigDecimal;
			} else {
				if (cnt_len.equals("")) {
					continue;
				} else {
					cnt_len = cnt_len.substring(0, cnt_len.length() - 1);
				}
			}
		}
		System.out.println(cnt_len);
	}
}
